#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Node {
    int v;
    int k;
};

int main() {
    // Otimização de I/O para programação competitiva
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    for (int i = 1; i <= n; ++i) {
        sort(adj[i].begin(), adj[i].end());
    }

    vector<vector<int>> rev(n + 1);
    vector<vector<int>> val_S(n + 1);
    vector<vector<int>> deg_S(n + 1);

    vector<Node> q;
    q.reserve(2 * m + n + 5);

    for (int i = 1; i <= n; ++i) {
        int d = adj[i].size();
        rev[i].resize(d);
        for (int j = 0; j < d; ++j) {
            int to = adj[i][j];
            auto it = lower_bound(adj[to].begin(), adj[to].end(), i);
            rev[i][j] = it - adj[to].begin();
        }
        val_S[i].assign(d + 1, 0);
        deg_S[i].assign(d + 1, 2);

        // Caso base: nenhum vértice seguinte
        val_S[i][d] = 1;
        deg_S[i][d] = 0;
        q.push_back({i, d});
    }

    int head = 0;
    while (head < (int)q.size()) {
        Node cur = q[head++];
        int v = cur.v;
        int k = cur.k;

        if (k == 0) {
            continue;
        }

        // 1) A aresta que chega em v vinda de u = adj[v][k - 1]
        int u = adj[v][k - 1];
        int r = rev[v][k - 1]; // posição de v em adj[u]
        int edge_val = 1 + val_S[v][k];

        deg_S[u][r]--;
        if (edge_val > val_S[u][r]) {
            val_S[u][r] = edge_val;
        }
        if (deg_S[u][r] == 0) {
            q.push_back({u, r});
        }

        // 2) O sufixo anterior S(v, k - 1)
        deg_S[v][k - 1]--;
        if (val_S[v][k] > val_S[v][k - 1]) {
            val_S[v][k - 1] = val_S[v][k];
        }
        if (deg_S[v][k - 1] == 0) {
            q.push_back({v, k - 1});
        }
    }

    for (int i = 1; i <= n; ++i) {
        cout << val_S[i][0] << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}
